// Open me and change the wage or the hours.
const wage = 15;
const hours = 40;            // one two-week paycheck
const gross = wage * hours;
const fica = gross * 0.0765;  // Social Security + Medicare
const federal = gross * 0.05;   // example rate: yours depends on your W-4
const state = gross * 0.03;     // example rate: varies by state
const net = gross - fica - federal - state;

await forever(async () => {
  await setSize(100);
  await say('Gross pay: $' + gross.toFixed(2));
  await wait(3);
  await setSize((gross - fica) / gross * 100);
  await say('FICA takes $' + fica.toFixed(2));
  await wait(3);
  await setSize((gross - fica - federal - state) / gross * 100);
  await say('Income tax takes $' + (federal + state).toFixed(2));
  await wait(3);
  await say('Take-home pay: $' + net.toFixed(2));
  await wait(3.4);
});

