  let spent = 0;
  for (let month = 1; month <= 12; month++) {
    spent += monthly;
    await setSize(spent / (monthly * 12) * 100);
    await say('Month ' + month + ': $' + spent.toFixed(2));
    await wait(1);
  }
  await wait(3);
});

