// A one-time deposit, growing a little every year.
const rate = 0.07;      // 7% is an example, not a promise
const startAge = 18;    // the age this money goes in
const firstAge = 18;    // both sprouts share one clock
const endAge = 65;

await forever(async () => {
  let balance = 1;              // every $1 you put in
  await setSize(100);
  for (let age = firstAge; age <= endAge; age++) {
    if (age > startAge) balance = balance * (1 + rate);
    await setSize(balance * 100);
    if (age % 5 === 0) await say('Age ' + age + ': $1 is now $' + balance.toFixed(2));
    await wait(0.35);
  }
  await wait(6);
});

