// Cash in a drawer earns nothing, and prices keep rising.
const inflation = 0.03;   // 3% is an example
const years = 24;

await forever(async () => {
  for (let year = 0; year <= years; year++) {
    const buys = 100 / Math.pow(1 + inflation, year);
    await setSize(buys);
    if (year % 6 === 0) await say('Year ' + year + ': $100 buys $' + buys.toFixed(0) + ' of stuff');
    await wait(0.5);
  }
  await wait(5);
  await setSize(100);
});

// Change the payment and press Save.
const balance = 500;     // bought on a card
const apr = 0.24;       // 24% a year is 2% a month
const payment = 15;     // try 10, then 25, then 50

await forever(async () => {
  let debt = balance;
  let paid = 0;
  await setOpacity(100);
  await setSize(100);
  await wait(2);
  for (let month = 1; month <= 60 && debt > 0; month++) {
    debt = debt * (1 + apr / 12) - payment;
    paid = paid + payment;
    if (debt > 0) {
      await setSize(debt / balance * 100);
      await say('Month ' + month + ': you still owe $' + debt.toFixed(0));
    } else {
      paid = paid + debt;     // the last payment is smaller
      await setOpacity(0);
      await say('Paid off in ' + month + ' months. Total paid: $' + paid.toFixed(0));
    }
    await wait(0.5);
  }
  await wait(5);
});

