await forever(async () => {
  await wait(12);
  await say('accident');
});

// Your emergency fund. Try insured = true.
const startingSavings = 1000;
const repair = 900;         // what the accident costs
const insured = false;
const deductible = 200;     // what you pay if you are insured

let savings = startingSavings;
whenSaid('accident', async () => {
  const cost = insured ? deductible : repair;
  savings = Math.max(0, savings - cost);
  await setSize(Math.max(1, savings / startingSavings * 100));
  await say('You paid $' + cost + '. Left: $' + savings);
  await wait(5);
  savings = startingSavings;
  await setSize(100);
});

